async function buildSpecimen(varMap, effectStyles) {
  let page = null;
  for (const p of figma.root.children) {
    if (p.name === PAGE_NAME) {
      await p.loadAsync();
      const kids = p.children.slice();
      for (const k of kids) k.remove();
      page = p;
      break;
    }
  }
  if (!page) {
    page = figma.createPage();
    page.name = PAGE_NAME;
  }
  await figma.setCurrentPageAsync(page);

  const W = 1240;
  const sections = [
    colorSection(varMap, W),
    typeSection(W),
    spaceRadiusSection(W),
    await elevationSection(effectStyles, W),
    marketSection(varMap, W),
  ];

  let x = 0;
  const made = [];
  for (const s of sections) {
    page.appendChild(s);
    s.x = x;
    s.y = 0;
    x += W + 80;
    made.push(s);
  }

  figma.viewport.scrollAndZoomIntoView(made);
  return made.length;
}

/* ══════════════════════════════════════════════════════════════
   6. 컴포넌트 페이지

   여기에는 props 조합을 실측한 컴포넌트만 둔다.
   CSS를 읽어 해석해 만들던 "신규 12종"은 측정 기반이 아니라 서로 겹치는
   문제가 있어 제거했다. 그 스펙은 FE-REQ-005와 pm/storyboard에 남아 있고,
   코드가 구현되면 Storybook 스토리가 생기므로 그때 실측으로 들어온다.
   ══════════════════════════════════════════════════════════════ */

const COMPONENT_PAGE = "SALT Components";

async function buildComponentsPage() {
  let page = null;
  for (const pg of figma.root.children) {
    if (pg.name === COMPONENT_PAGE) {
      await pg.loadAsync();
      const kids = pg.children.slice();
      for (const k of kids) k.remove();
      page = pg;
      break;
    }
  }
  if (!page) {
    page = figma.createPage();
    page.name = COMPONENT_PAGE;
  }
  await figma.setCurrentPageAsync(page);

  const root = box("Components", {
    dir: "VERTICAL", gap: 96, pad: 80, width: 1600, bg: "#FFFFFF", clip: false,
  });
  page.appendChild(root);

  const head = box("head", { dir: "VERTICAL", gap: 6, width: 1440 });
  add(head, [
    text("구현됨 — props 조합 실측", { size: 30, lh: 40, ls: -3, weight: "Bold" }),
    text(
      "Storybook args로 prop을 주입해 실제로 렌더시킨 결과를 측정했다. " +
        "variant 속성이 컴포넌트의 실제 props이므로 Figma 속성 패널에서 드롭다운으로 고를 수 있다.",
      { size: 15, lh: 22.5, color: "#6B7684", width: 1440 }
    ),
  ]);
  head.layoutAlign = "STRETCH";
  root.appendChild(head);

  const notes = [];
  const result = await buildPropsComponents(page, root, notes);

  figma.viewport.scrollAndZoomIntoView([root]);
  return {
    propsComps: result.comps,
    propsVariants: result.variants,
    propsSets: result.sets,
    notes: notes,
  };
}

/* ══════════════════════════════════════════════════════════════
   8. Storybook 실측 미러

   MEASURED는 실행 중인 Storybook의 모든 스토리를 브라우저에서
   getBoundingClientRect + getComputedStyle로 측정한 결과다.
   CSS를 해석하지 않고 "실제로 그려진 것"을 좌표째 옮기므로
   Storybook과 어긋날 여지가 없다.

   재측정 방법은 README의 "Storybook 재측정" 절에 있다.
   ══════════════════════════════════════════════════════════════ */

const STORYBOOK_PAGE = "SALT Storybook";

// CSS font-weight → Figma 스타일명
const WEIGHT_STYLE = {
  "100": "Regular", "200": "Regular", "300": "Regular",
  "400": "Regular", "normal": "Regular",
  "500": "Medium",
  "600": "SemiBold",
  "700": "Bold", "bold": "Bold", "800": "Bold", "900": "Bold",
};

const ALIGN_MAP = { left: "LEFT", center: "CENTER", right: "RIGHT", justify: "JUSTIFIED", start: "LEFT", end: "RIGHT" };

function paintOf(v) {
  if (!v) return null;
  if (typeof v === "string") return solid(v);
  const p = solid(v.hex);
  if (v.a !== undefined && v.a < 1) p.opacity = v.a;
  return p;
}

// CSS linear-gradient → Figma GRADIENT_LINEAR
// CSS 0deg는 "to top", Figma 기본 축은 "to right"이므로 -90도 보정한다.
function gradientTransform(angleDeg) {
  const a = ((angleDeg - 90) * Math.PI) / 180;
  const cos = Math.cos(a);
  const sin = Math.sin(a);
  return [
    [cos, sin, 0.5 - 0.5 * cos - 0.5 * sin],
    [-sin, cos, 0.5 + 0.5 * sin - 0.5 * cos],
  ];
}

function parseGradient(css) {
  if (css.indexOf("linear-gradient") !== 0) return null;
  const inner = css.slice(css.indexOf("(") + 1, css.lastIndexOf(")"));
  const parts = inner.split(/,(?![^(]*\))/).map(function (x) { return x.trim(); });
  let angle = 180; // 각도 생략 시 CSS 기본값은 to bottom
  if (/^-?[\d.]+deg$/.test(parts[0])) angle = parseFloat(parts.shift());
  else if (parts[0].indexOf("to ") === 0) {
    const dir = parts.shift();
    const map = { "to top": 0, "to right": 90, "to bottom": 180, "to left": 270,
      "to top right": 45, "to bottom right": 135, "to bottom left": 225, "to top left": 315 };
    angle = map[dir] === undefined ? 180 : map[dir];
  }
  const stops = [];
  for (let i = 0; i < parts.length; i++) {
    const m = parts[i].match(/(rgba?\([^)]+\)|#[0-9a-fA-F]{3,8})\s*([\d.]+)?%?/);
    if (!m) continue;
    let r = 0, g = 0, b = 0, a = 1;
    if (m[1].charAt(0) === "#") {
      const c = hexToRgb(m[1]);
      r = c.r; g = c.g; b = c.b; a = hexAlpha(m[1]);
    } else {
      const c = m[1].slice(m[1].indexOf("(") + 1, -1).split(",").map(function (x) { return parseFloat(x); });
      r = c[0] / 255; g = c[1] / 255; b = c[2] / 255;
      if (c.length === 4) a = c[3];
    }
    const pos = m[2] !== undefined ? parseFloat(m[2]) / 100
      : (parts.length === 1 ? 0 : i / (parts.length - 1));
    stops.push({ position: Math.min(Math.max(pos, 0), 1), color: { r: r, g: g, b: b, a: a } });
  }
  if (stops.length < 2) return null;
  stops.sort(function (x, y) { return x.position - y.position; });
  return {
    type: "GRADIENT_LINEAR",
    gradientTransform: gradientTransform(angle),
    gradientStops: [stops[0], stops[stops.length - 1]],
    stopCount: stops.length,
  };
}

// "rgba(25, 31, 40, 0.04) 0px 1px 2px 0px, ..." 형태를 DROP_SHADOW 배열로
function parseShadows(css) {
  const out = [];
  const parts = css.split(/,(?![^(]*\))/);
  for (const raw of parts) {
    const part = raw.trim();
    if (!part || part === "none") continue;
    const col = part.match(/rgba?\(([^)]+)\)/);
    const nums = part.replace(/rgba?\([^)]+\)/, "").match(/-?\d*\.?\d+px/g) || [];
    if (nums.length < 2) continue;
    const px = nums.map(function (n) { return parseFloat(n); });
    let a = 1, r = 0, g = 0, b = 0;
    if (col) {
      const c = col[1].split(",").map(function (x) { return parseFloat(x); });
      r = c[0] / 255; g = c[1] / 255; b = c[2] / 255;
      if (c.length === 4) a = c[3];
    }
    out.push({
      type: part.indexOf("inset") > -1 ? "INNER_SHADOW" : "DROP_SHADOW",
      color: { r: r, g: g, b: b, a: a },
      offset: { x: px[0], y: px[1] },
      radius: px[2] === undefined ? 0 : px[2],
      spread: px[3] === undefined ? 0 : px[3],
      visible: true, blendMode: "NORMAL",
    });
  }
  return out;
}

// Inter에 글리프가 없어 Figma에서 사라지는 기호들. 실측 데이터 전수 조사로 9종을 찾았고
// 그중 도형으로 그릴 수 있는 것은 벡터로 대체한다(₩·₿는 Inter에 있어 텍스트로 둔다).
const GLYPH_SVG = {
  "★": '<path d="M12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26Z" fill="%C"/>',
  "☆": '<path d="M12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26Z" fill="none" stroke="%C" stroke-width="1.6"/>',
  "●": '<circle cx="12" cy="12" r="7.5" fill="%C"/>',
  "⬨": '<path d="M12 3 19 12 12 21 5 12Z" fill="none" stroke="%C" stroke-width="1.6"/>',
  "→": '<path d="M4 12H20M14 6l6 6-6 6" fill="none" stroke="%C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>',
  "↑": '<path d="M12 20V4M6 10l6-6 6 6" fill="none" stroke="%C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>',
  "↓": '<path d="M12 4v16M6 14l6 6 6-6" fill="none" stroke="%C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>',
};

function hexOf(v) {
  if (!v) return "#000000";
  return typeof v === "string" ? v : v.hex;
}

// 텍스트가 기호 문자만으로 이루어져 있으면 벡터로 그린다.
function glyphOnly(str) {
  const chars = str.replace(/\s/g, "").split("");
  if (!chars.length) return null;
  for (const c of chars) if (!GLYPH_SVG[c]) return null;
  return chars;
}

// 요소 하나를 프레임으로 만든다. 배경·테두리·radius·그림자·클리핑을 담는다.
function makeMeasuredFrame(n) {
  const w = Math.max(n.w, 1);
  const h = Math.max(n.h, 1);
  const f = figma.createFrame();
  f.name = n.t;
  f.layoutMode = "NONE";
  // overflow:hidden 이면 실제로 클리핑한다. 이걸 빼면 스크롤 영역 내용이
  // 부모 밖으로 최대 246px 튀어나온다(실측 172건).
  f.clipsContent = !!n.clip;
  f.resize(w, h);
  const bgPaint = paintOf(n.bg);
  f.fills = bgPaint ? [bgPaint] : [];
  if (n.r) {
    f.topLeftRadius = n.r[0];
    f.topRightRadius = n.r[1];
    f.bottomRightRadius = n.r[2];
    f.bottomLeftRadius = n.r[3];
  }
  if (n.bw) {
    const live = [];
    for (let i = 0; i < 4; i++) {
      if (n.bw[i] > 0) live.push({ i: i, c: (n.bc && n.bc[i]) || "#000000" });
    }
    const uniq = [];
    for (const L of live) if (uniq.indexOf(L.c) === -1) uniq.push(L.c);
    if (uniq.length === 1) {
      const p = paintOf(uniq[0]);
      f.strokes = p ? [p] : [];
      f.strokeAlign = "INSIDE";
      f.strokeTopWeight = n.bw[0];
      f.strokeRightWeight = n.bw[1];
      f.strokeBottomWeight = n.bw[2];
      f.strokeLeftWeight = n.bw[3];
    } else if (uniq.length > 1) {
      for (const L of live) {
        const line = figma.createRectangle();
        line.name = ["border-top", "border-right", "border-bottom", "border-left"][L.i];
        const t = n.bw[L.i];
        if (L.i === 0) { line.resize(w, t); }
        else if (L.i === 1) { line.resize(t, h); }
        else if (L.i === 2) { line.resize(w, t); }
        else { line.resize(t, h); }
        const lp = paintOf(L.c);
        line.fills = lp ? [lp] : [];
        f.appendChild(line);
        line.x = L.i === 1 ? w - n.bw[1] : 0;
        line.y = L.i === 2 ? h - n.bw[2] : 0;
      }
    }
  }
  if (n.shadow) {
    const eff = parseShadows(n.shadow);
    if (eff.length) f.effects = eff;
  }
  if (n.o !== undefined) f.opacity = n.o;
  return f;
}

// 요소의 자기 텍스트를 프레임 안에 올린다. 좌표는 프레임 기준 상대값.
async function addMeasuredText(frame, n, notes) {
  const glyphs = glyphOnly(n.text);
  const bx = (n.tx === undefined ? n.x : n.tx) - n.x;
  const by = (n.ty === undefined ? n.y : n.ty) - n.y;
  const bw = Math.max(n.tw === undefined ? n.w : n.tw, 1);
  const bh = Math.max(n.th === undefined ? n.h : n.th, 1);

  if (glyphs) {
    // Inter에 없는 기호는 벡터로 대체한다(없으면 화면에서 사라진다)
    const size = Math.max(n.fs || 14, 8);
    for (let i = 0; i < glyphs.length; i++) {
      const body = GLYPH_SVG[glyphs[i]].replace(/%C/g, hexOf(n.fg));
      let node;
      try {
        node = figma.createNodeFromSvg(
          '<svg width="24" height="24" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">' + body + "</svg>"
        );
      } catch (e) { continue; }
      node.name = glyphs[i];
      frame.appendChild(node);
      try { node.resize(size, size); } catch (e) {}
      node.x = bx + i * size * 1.1;
      node.y = by + (bh - size) / 2;
    }
    notes.push("기호 글리프를 벡터로 대체: " + n.text.slice(0, 4));
    return;
  }

  const style = WEIGHT_STYLE[n.fw] || "Regular";
  const t = figma.createText();
  t.name = n.text.slice(0, 24);
  t.fontName = { family: FAMILY, style: wStyle(style) };
  t.fontSize = n.fs;
  if (n.lh) t.lineHeight = { value: n.lh, unit: "PIXELS" };
  if (n.ls) t.letterSpacing = { value: n.ls, unit: "PIXELS" };
  t.characters = n.text;
  const paint = paintOf(n.fg);
  t.fills = paint ? [paint] : [];
  const align = ALIGN_MAP[n.ta] || "LEFT";
  t.textAlignHorizontal = align;

  const lineH = n.lh || n.fs * 1.2;
  const multiline = bh > lineH * 1.6;
  if (multiline) {
    t.textAutoResize = "HEIGHT"; // 폭 유지 → 줄바꿈 보존, 세로 잘림 없음
    frame.appendChild(t);
    try { t.resize(bw + 2, t.height); } catch (e) {}
    t.x = bx;
    t.y = by;
  } else {
    t.textAutoResize = "WIDTH_AND_HEIGHT"; // hug → 잘리지 않음
    frame.appendChild(t);
    if (align === "RIGHT") t.x = bx + bw - t.width;
    else if (align === "CENTER") t.x = bx + (bw - t.width) / 2;
    else t.x = bx;
    t.y = by + (bh - t.height) / 2;
  }
  if (n.fvn) notes.push("tabular-nums: " + n.text.slice(0, 12));
}

// 클리핑 조상과 교차시켜 실제로 보이는 범위만 합산한다.
function visibleBounds(nodes, root) {
  let minX = 0, minY = 0, maxX = root.w, maxY = root.h;
  // stack[i] = { d, clipRect|null }
  const stack = [{ d: -1, clip: null }];

  for (const n of nodes) {
    while (stack.length > 1 && stack[stack.length - 1].d >= n.d) stack.pop();
    const inherited = stack[stack.length - 1].clip;

    const x0 = Math.min(n.x, n.tx === undefined ? n.x : n.tx);
    const y0 = Math.min(n.y, n.ty === undefined ? n.y : n.ty);
    const x1 = Math.max(n.x + n.w, (n.tx === undefined ? n.x : n.tx) + (n.tw === undefined ? n.w : n.tw));
    const y1 = Math.max(n.y + n.h, (n.ty === undefined ? n.y : n.ty) + (n.th === undefined ? n.h : n.th));

    let vx0 = x0, vy0 = y0, vx1 = x1, vy1 = y1;
    if (inherited) {
      vx0 = Math.max(vx0, inherited.x0);
      vy0 = Math.max(vy0, inherited.y0);
      vx1 = Math.min(vx1, inherited.x1);
      vy1 = Math.min(vy1, inherited.y1);
    }
    if (vx1 > vx0 && vy1 > vy0) {
      if (vx0 < minX) minX = vx0;
      if (vy0 < minY) minY = vy0;
      if (vx1 > maxX) maxX = vx1;
      if (vy1 > maxY) maxY = vy1;
    }

    // 이 노드가 클리핑하면 자손의 가시 범위를 자기 박스로 제한한다
    let ownClip = inherited;
    if (n.clip) {
      const c = { x0: n.x, y0: n.y, x1: n.x + n.w, y1: n.y + n.h };
      ownClip = inherited
        ? { x0: Math.max(c.x0, inherited.x0), y0: Math.max(c.y0, inherited.y0),
            x1: Math.min(c.x1, inherited.x1), y1: Math.min(c.y1, inherited.y1) }
        : c;
    }
    stack.push({ d: n.d, clip: ownClip });
  }
  return { minX: minX, minY: minY, maxX: maxX, maxY: maxY };
}

// depth 배열을 DOM 계층 그대로 Figma에 재구성한다.
// 평면으로 그리면 overflow:hidden 클리핑이 적용될 부모가 없다.
async function renderMeasuredTree(canvas, nodes, offX, offY, notes) {
  // stack[i] = { d, frame, absX, absY }
  const stack = [{ d: -1, frame: canvas, absX: offX, absY: offY }];

  for (const n of nodes) {
    while (stack.length > 1 && stack[stack.length - 1].d >= n.d) stack.pop();
    const parent = stack[stack.length - 1];

    if (n.t === "svg") {
      let node;
      try {
        node = figma.createNodeFromSvg(n.svg);
      } catch (e) {
        notes.push("svg 실패: " + e.message);
        continue;
      }
      node.name = "svg";
      parent.frame.appendChild(node);
      node.x = n.x - parent.absX;
      node.y = n.y - parent.absY;
      try { node.resize(Math.max(n.w, 1), Math.max(n.h, 1)); } catch (e) {}
      continue;
    }

    const f = makeMeasuredFrame(n);
    parent.frame.appendChild(f);
    f.x = n.x - parent.absX;
    f.y = n.y - parent.absY;

    if (n.src) {
      // 외부 URL 이미지는 받아올 수 없다 → 자리표시자
      f.fills = [solid("#F2F4F6")];
      notes.push("외부 <img> 자리표시자: " + n.src);
    }
    if (n.bgImage) {
      const grad = parseGradient(n.bgImage);
      if (grad) {
        const stops = grad.stopCount;
        delete grad.stopCount;
        f.fills = [grad];
        if (stops > 2) notes.push("다중 스톱 그라디언트를 양 끝 2색으로 축약: " + n.t);
      } else {
        notes.push("gradient 아닌 background-image 미지원: " + n.t);
      }
    }
    if (n.text) await addMeasuredText(f, n, notes);

    stack.push({ d: n.d, frame: f, absX: n.x, absY: n.y });
  }
}

// 스토리 id에서 표시용 그룹명을 만든다: "components-button--primary" → "Button"
function groupOf(id) {
  const head = id.split("--")[0];
  const seg = head.split("-");
  const drop = { components: 1, layout: 1, typography: 1, charts: 1, filter: 1 };
  const kept = seg.filter(function (s) { return !drop[s]; });
  return (kept.length ? kept : seg).map(function (s) {
    return s.charAt(0).toUpperCase() + s.slice(1);
  }).join(" ");
}

// 스토리 id에서 variant 값을 만든다: "components-button--primary" → "primary"
function variantSlug(id) {
  const i = id.indexOf("--");
  return i === -1 ? id : id.slice(i + 2);
}

async function buildStorybookPage() {
  let page = null;
  for (const pg of figma.root.children) {
    if (pg.name === STORYBOOK_PAGE) {
      await pg.loadAsync();
      const kids = pg.children.slice();
      for (const k of kids) k.remove();
      page = pg;
      break;
    }
  }
  if (!page) {
    page = figma.createPage();
    page.name = STORYBOOK_PAGE;
  }
  await figma.setCurrentPageAsync(page);

  const ids = Object.keys(MEASURED).sort();
  const groups = {};
  for (const id of ids) {
    const g = groupOf(id);
    if (!groups[g]) groups[g] = [];
    groups[g].push(id);
  }

  const root = box("Storybook Components", {
    dir: "VERTICAL", gap: 96, pad: 80, width: 1600, bg: "#FFFFFF", clip: false,
  });
  page.appendChild(root);

  const notes = [];
  let stories = 0;
  let sets = 0;

  for (const g of Object.keys(groups).sort()) {
    const made = [];

    for (const id of groups[g]) {
      const story = MEASURED[id];
      // 프레임이 아니라 실제 Component로 만든다 → 라이브러리로 쓸 수 있다
      const c = figma.createComponent();
      c.name = groups[g].length > 1 ? "story=" + variantSlug(id) : g;
      c.layoutMode = "NONE";
      c.clipsContent = false;
      c.fills = [solid("#FFFFFF")];
      c.description = id + " · Storybook 실측";

      const visible = visibleBounds(story.nodes, story.root);
      c.resize(
        Math.max(visible.maxX - visible.minX, 1),
        Math.max(visible.maxY - visible.minY, 1)
      );
      page.appendChild(c); // combineAsVariants는 같은 부모의 형제만 묶는다

      if (story.nodes.length) {
        await renderMeasuredTree(c, story.nodes, visible.minX, visible.minY, notes);
      }
      made.push(c);
      stories++;
    }

    let node;
    if (made.length > 1) {
      node = figma.combineAsVariants(made, page);
      node.name = g;
      node.layoutMode = "HORIZONTAL";
      node.layoutWrap = "WRAP";
      node.itemSpacing = 48;
      node.counterAxisSpacing = 56;
      node.primaryAxisSizingMode = "FIXED";
      node.counterAxisSizingMode = "AUTO";
      node.paddingTop = 40;
      node.paddingBottom = 40;
      node.paddingLeft = 40;
      node.paddingRight = 40;
      node.resize(1440, node.height || 200);
      node.clipsContent = false;
      node.counterAxisAlignItems = "MIN";
      sets++;
    } else {
      node = made[0];
    }
    // 세트일 때만 세트 설명을 쓴다. 단독 컴포넌트는 스토리 id가 담긴
    // 자기 설명을 유지해야 어느 스토리에서 왔는지 추적할 수 있다.
    if (made.length > 1) {
      node.description = g + " · Storybook " + groups[g].length + "개 스토리 실측";
    }

    const section = box("section · " + g, { dir: "VERTICAL", gap: 40, clip: false });
    const head = box("head", { dir: "VERTICAL", gap: 4, width: 1440 });
    add(head, [
      text(g, { size: 30, lh: 40, ls: -3, weight: "Bold" }),
      text(groups[g].length + "개 스토리 · variant는 story=<스토리명>", {
        size: 13, lh: 19.5, color: "#8B95A1", width: 1440,
      }),
    ]);
    section.appendChild(head);
    section.appendChild(node);
    root.appendChild(section);
  }

  figma.viewport.scrollAndZoomIntoView([root]);
  return { stories: stories, sets: sets, notes: notes };
}


/* ══════════════════════════════════════════════════════════════
   9. props 조합 실측 컴포넌트

   MEASURED_PROPS는 Storybook args로 prop을 주입해 렌더시킨 결과를
   측정한 것이다. variant 이름이 "variant=ghost, size=lg" 형태라서
   Figma가 variant 속성(=props)을 그대로 인식하고, 속성 패널에
   드롭다운으로 노출된다.
   ══════════════════════════════════════════════════════════════ */

async function buildPropsComponents(page, root, notes) {
  const comps = Object.keys(MEASURED_PROPS).sort();
  let variants = 0;
  let sets = 0;

  for (const comp of comps) {
    const table = MEASURED_PROPS[comp];
    const names = Object.keys(table);
    const made = [];

    for (const vname of names) {
      const t = table[vname];
      const c = figma.createComponent();
      c.name = vname; // "variant=ghost, size=lg, disabled=false" → Figma가 props로 인식
      c.layoutMode = "NONE";
      c.clipsContent = false;
      c.fills = [solid("#FFFFFF")];

      const visible = visibleBounds(t.nodes, t.root);
      c.resize(
        Math.max(visible.maxX - visible.minX, 1),
        Math.max(visible.maxY - visible.minY, 1)
      );
      page.appendChild(c);
      if (t.nodes.length) {
        await renderMeasuredTree(c, t.nodes, visible.minX, visible.minY, notes);
      }
      made.push(c);
      variants++;
    }

    let node;
    if (made.length > 1) {
      node = figma.combineAsVariants(made, page);
      node.name = comp;
      node.layoutMode = "HORIZONTAL";
      node.layoutWrap = "WRAP";
      node.itemSpacing = 32;
      node.counterAxisSpacing = 40;
      node.primaryAxisSizingMode = "FIXED";
      node.counterAxisSizingMode = "AUTO";
      node.paddingTop = 40;
      node.paddingBottom = 40;
      node.paddingLeft = 40;
      node.paddingRight = 40;
      node.resize(1440, node.height || 200);
      node.clipsContent = false;
      node.counterAxisAlignItems = "MIN";
      sets++;
    } else {
      node = made[0];
      node.name = comp;
    }

    // 어떤 prop을 어떤 값으로 조합했는지 설명에 남긴다
    const propKeys = [];
    for (const n of names) {
      for (const part of n.split(", ")) {
        const k = part.split("=")[0];
        if (propKeys.indexOf(k) === -1) propKeys.push(k);
      }
    }
    node.description =
      comp + " · props(" + propKeys.join(" · ") + ") 조합 " + names.length +
      "개를 Storybook args로 주입해 실측";

    const section = box("section · " + comp, { dir: "VERTICAL", gap: 40, clip: false });
    const head = box("head", { dir: "VERTICAL", gap: 4, width: 1440 });
    add(head, [
      text(comp, { size: 30, lh: 40, ls: -3, weight: "Bold" }),
      text("props: " + propKeys.join(" · ") + " — 조합 " + names.length + "개 실측", {
        size: 13, lh: 19.5, color: "#8B95A1", width: 1440,
      }),
    ]);
    section.appendChild(head);
    section.appendChild(node);
    root.appendChild(section);
  }

  return { variants: variants, sets: sets, comps: comps.length };
}

/* ══════════════════════════════════════════════════════════════
   7. 엔트리
   ══════════════════════════════════════════════════════════════ */

async function main() {
  let cmd = figma.command || "all";
  // "...-target"은 같은 작업을 Target 값으로 돌리는 변형이다.
  const preferTarget = cmd.slice(-7) === "-target";
  if (preferTarget) cmd = cmd.slice(0, -7);
  const wantFoundation = cmd === "all" || cmd === "everything";
  const wantComponents = cmd === "components" || cmd === "everything";
  const wantStorybook = cmd === "storybook" || cmd === "everything";
  await loadFonts();

  let vars = { collection: null, map: {}, count: 0, changed: 0, modeLimited: false };
  let effects = null;
  const done = [];

  if (wantFoundation || cmd === "variables") {
    vars = await buildVariables(preferTarget);
    if (vars.modeLimited) {
      // 무료 플랜: 모드가 1개뿐이다. 어느 값 세트를 넣었는지 분명히 알린다.
      done.push(
        "Variable " + vars.count + "개(Mode 1 · " + vars.primaryMode + " 값) — " +
        "이 플랜은 모드가 1개로 제한됩니다. Current↔Target 차이 " + vars.changed +
        "개는 각 Variable description과 Color 섹션 화살표로 표시했습니다"
      );
    } else {
      done.push(
        "Variable " + vars.count + "개(Mode " + vars.modes.length + ": " +
        vars.modes.join("/") + " · 차이 " + vars.changed + "개)"
      );
    }
  } else {
    vars = await findVariables();
  }

  if (wantFoundation || cmd === "styles") {
    const n = await buildTextStyles();
    effects = await buildEffectStyles();
    done.push("Text Style " + n + "개", "Effect Style " + Object.keys(effects).length + "개");
  } else {
    effects = await effectStyleMap();
  }

  if (wantFoundation || cmd === "specimen") {
    const n = await buildSpecimen(vars.map, effects);
    done.push("스펙시멘 섹션 " + n + "개");
    if (!vars.collection) {
      done.push("⚠ Collection \"" + COLLECTION + "\"이 없어 fill을 Variable에 바인딩하지 못했습니다");
    }
  }

  if (wantComponents) {
    const r = await buildComponentsPage();
    done.push(
      "props 실측 컴포넌트 " + r.propsComps + "종(variant " + r.propsVariants +
      "개 / Set " + r.propsSets + "개)"
    );
  }

  if (wantStorybook) {
    const sb = await buildStorybookPage();
    done.push(
      "Storybook 실측 컴포넌트 " + sb.stories + "개 / Component Set " + sb.sets + "개"
    );
    if (sb.notes.length) {
      // 같은 경고는 한 번만 알린다
      const uniq = [];
      for (const nt of sb.notes) {
        const key = nt.split(":")[0];
        if (uniq.indexOf(key) === -1) uniq.push(key);
      }
      done.push("참고 " + uniq.length + "종: " + uniq.slice(0, 3).join(" / "));
    }
  }

  figma.closePlugin(
    "SALT 생성 완료" + (preferTarget ? " (Target 값)" : "") + " — " + done.join(" · ")
  );
}

main().catch(function (e) {
  figma.closePlugin("실패: " + (e && e.message ? e.message : String(e)));
});
